.app-shell { box-sizing: border-box; width: 100%; max-width: 1120px; margin: 0 auto; padding: 16px; }
.app-header { margin-bottom: 24px; }
.app-header h1 { margin: 0 0 8px; font-size: 24px; line-height: 32px; }
.app-header p { max-width: 720px; margin: 0; color: #B8BDD2; }
.game-area { display: grid; gap: 16px; min-width: 0; }
.game-stats { display: flex; flex-wrap: wrap; gap: 8px 24px; }
.game-stats p { margin: 0; font-weight: 600; }
.resume-button { justify-self: start; }
.win-banner {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px 16px;
  padding: 12px 16px;
  border: 1px solid #8BEA7D;
  border-radius: 12px;
  background: #141827;
  color: #F4F6FF;
}
.win-banner--pulse { animation: win-pulse 600ms ease-out 1; }
@keyframes win-pulse {
  0% { transform: scale(1); box-shadow: 0 0 0 0 #8BEA7D66; }
  45% { transform: scale(1.015); box-shadow: 0 0 0 8px #8BEA7D00; }
  100% { transform: scale(1); box-shadow: 0 0 0 0 #8BEA7D00; }
}
@media (prefers-reduced-motion: reduce) { .win-banner--pulse { animation: none; } }
@media (max-width: 400px) {
  .app-shell { padding: 16px; }
  .game-stats { gap: 8px 12px; }
}

