    expect(replayGame('{"version":1,"boardCode":"np1-4-1","actions":[{"atMs":2,"index":0},{"atMs":1,"index":1}],"endMs":2}')).toBeNull();
    expect(replayGame('{"version":1,"boardCode":"np1-4-1","actions":[],"endMs":0,"extra":1}')).toBeNull();
