```import { defineConfig, devices } from '@playwright/test';

export default defineConfig({
  testDir: './e2e',
  fullyParallel: true,
  reporter: 'list',
  use: { ...devices['Desktop Chrome'], baseURL: 'http://127.0.0.1:4173', headless: true },
  projects: [{ name: 'chromium', use: { ...devices['Desktop Chrome'] } }],
  webServer: {
    command: 'npm run preview -- --host 127.0.0.1',
    url: 'http://127.0.0.1:4173',
    reuseExistingServer: false,
  },
});
import { expect, test, type Page } from '@playwright/test';
import { mkdir, writeFile } from 'node:fs/promises';
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';

const DECK = [6, 7, 0, 5, 2, 2, 0, 5, 3, 7, 1, 6, 4, 4, 1, 3];
const PAIRS = [[0, 11], [1, 9], [2, 6], [3, 7], [4, 5], [8, 15], [10, 14], [12, 13]] as const;

test('keyboard and accessibility tree support a complete 4x4 game', async ({ page, browser }, testInfo) => {
  await page.goto('/');
  await expect(page.getByLabel('Grid size')).toHaveValue('4');
  const newGame = page.getByRole('button', { name: 'New Game' });
  await newGame.focus();
  await page.keyboard.press('Enter');

  const summary = page.locator('summary');
  await summary.focus();
  await page.keyboard.press('Enter');
  const boardCode = page.getByLabel('Board code');
  await boardCode.fill('np1-4-1');
  const loadBoard = page.getByRole('button', { name: 'Load board' });
  await loadBoard.focus();
  await page.keyboard.press('Enter');
  await expect(boardCode).toHaveValue('np1-4-1');

  for (let index = 0; index < 4; index += 1) await page.keyboard.press('Tab');
  await expectFocusedCard(page, 0, 'closed');
  await page.keyboard.press('ArrowLeft');
  await expectFocusedCard(page, 0, 'closed');
  await page.keyboard.press('Enter');
  await expect(page.getByRole('button', { name: 'Row 1, column 1, cyan solid plus, marker top, revealed' })).toBeFocused();
  await moveTo(page, 0, 11, 4);
  await page.keyboard.press('Space');
  await expect(page.getByRole('button', { name: 'Row 3, column 4, cyan solid plus, marker top, matched' })).toHaveAttribute('aria-disabled', 'true');
  await expect(page.getByRole('status')).toHaveText('Pair found. 1 pair matched.');

  const earlyTree = await page.locator('body').ariaSnapshot();
  expect(earlyTree).toContain('Row 1, column 1, cyan solid plus, marker top, matched');
  expect(earlyTree).toContain('Pair found. 1 pair matched.');

  let current = 11;
  for (let pairIndex = 1; pairIndex < PAIRS.length; pairIndex += 1) {
    const pair = PAIRS[pairIndex];
    if (!pair) continue;
    const [first, second] = pair;
    await moveTo(page, current, first, 4);
    await page.keyboard.press(pairIndex % 2 === 0 ? 'Space' : 'Enter');
    await moveTo(page, first, second, 4);
    await page.keyboard.press(pairIndex % 2 === 0 ? 'Enter' : 'Space');
    current = second;
    await expect(page.locator('.game-stats')).toContainText(`Pairs: ${pairIndex + 1}/8`);
  }
  expect(DECK[0]).toBe(DECK[11]);
  for (const [first, second] of PAIRS) expect(DECK[first]).toBe(DECK[second]);
  await expect(page.getByRole('status')).toHaveText(/^Pair found\. All pairs found in 8 moves and \d+:\d{2}\.$/);
  await expect(page.locator('.win-banner')).toContainText('All pairs found!');
  await expect(page.locator('.game-stats')).toContainText('Moves: 8');

  const completeTree = await page.locator('body').ariaSnapshot();
  expect(completeTree).toContain('All pairs found!');
  const evidence = [
    `Playwright: 1.64.1`,
    `Browser: Chromium ${browser.version()}`,
    'Screen reader used: no (browser accessibility tree captured for automated evidence)',
    '',
    'During play:',
    earlyTree,
    '',
    'After the final match:',
    completeTree,
  ].join('\n');
  await mkdir(resolve('artifacts'), { recursive: true });
  await writeFile(resolve('artifacts/accessibility-tree.txt'), evidence, 'utf8');
  await testInfo.attach('accessibility-tree.txt', { body: Buffer.from(evidence), contentType: 'text/plain' });

  await page.keyboard.press('Tab');
  await expect(page.locator('summary')).toBeFocused();
  await page.keyboard.press('Shift+Tab');
  await page.keyboard.press('Shift+Tab');
  await expect(page.getByRole('button', { name: 'Restart' })).toBeFocused();
  await page.keyboard.press('Shift+Tab');
  await expect(page.getByRole('button', { name: 'New Game' })).toBeFocused();
  await page.keyboard.press('Enter');
  await expect(page.locator('.game-stats')).toContainText('Moves: 0');
  await expect(page.locator('.game-stats')).toContainText('Pairs: 0/8');
});

test('the distribution opens from disk and local HTTP preferences preserve unrelated keys', async ({ browser, baseURL }) => {
  const offlineContext = await browser.newContext();
  await offlineContext.route('**/*', (route) => {
    const protocol = new URL(route.request().url()).protocol;
    return protocol === 'file:' ? route.continue() : route.abort();
  });
  const offlinePage = await offlineContext.newPage();
  await offlinePage.goto(pathToFileURL(resolve('dist/index.html')).href);
  await expect(offlinePage.getByRole('heading', { name: 'Neon Pairs' })).toBeVisible();
  await expect(offlinePage.locator('[aria-label="Game board"] button')).toHaveCount(16);
  await offlineContext.close();

  if (!baseURL) throw new Error('Playwright preview server did not provide a base URL.');
  const httpContext = await browser.newContext();
  const page = await httpContext.newPage();
  await page.goto(baseURL);
  await page.evaluate(() => {
    localStorage.setItem('unrelated-project-key', 'keep-me');
    localStorage.setItem('neon-pairs.preferences.v1', JSON.stringify({ size: 6 }));
  });
  await page.reload();
  await expect(page.getByLabel('Grid size')).toHaveValue('6');
  await expect(page.locator('[aria-label="Game board"] button')).toHaveCount(36);
  await page.getByLabel('Grid size').selectOption('4');
  const values = await page.evaluate(() => ({
    size: localStorage.getItem('neon-pairs.preferences.v1'),
    unrelated: localStorage.getItem('unrelated-project-key'),
  }));
  expect(values.size).toBe('{"size":4}');
  expect(values.unrelated).toBe('keep-me');
  await httpContext.close();
});

async function moveTo(page: Page, from: number, to: number, size: number): Promise<void> {
  let row = Math.floor(from / size);
  let column = from % size;
  const targetRow = Math.floor(to / size);
  const targetColumn = to % size;
  while (row < targetRow) { await page.keyboard.press('ArrowDown'); row += 1; }
  while (row > targetRow) { await page.keyboard.press('ArrowUp'); row -= 1; }
  while (column < targetColumn) { await page.keyboard.press('ArrowRight'); column += 1; }
  while (column > targetColumn) { await page.keyboard.press('ArrowLeft'); column -= 1; }
  await expectFocusedCard(page, to, 'closed');
}

async function expectFocusedCard(page: Page, index: number, state: 'closed'): Promise<void> {
  const row = Math.floor(index / 4) + 1;
  const column = index % 4 + 1;
  await expect(page.getByRole('button', { name: `Row ${row}, column ${column}, ${state}` })).toBeFocused();
}

