    board: Board;
    matched: readonly number[];
    selection: Selection;
    moves: number;
    elapsedMs: number;
    started: boolean;
}>;
export type Snapshot = Readonly<{
    version: 1;
    boardCode: string;
    matched: readonly number[];
    selection: Selection;
    moves: number;
    elapsedMs: number;
    started: boolean;
}>;

