test('16x16 remains within the page and keeps its 44px cards at narrow and zoom-equivalent widths', async ({ page }) => {
  await page.setViewportSize({ width: 360, height: 800 });
  await page.goto('/');
  await page.getByLabel('Grid size').selectOption('16');
  const board = page.locator('[aria-label="Game board"]');
  await expect(board.locator('button')).toHaveCount(256);
  const mobile = await page.locator('.card').first().evaluate((card) => {
    const scroll = card.parentElement?.parentElement;
    const rectangle = card.getBoundingClientRect();
    return {
      width: rectangle.width,
      height: rectangle.height,
      pageWidth: card.ownerDocument.documentElement.scrollWidth,
      viewportWidth: card.ownerDocument.documentElement.clientWidth,
      scrollWidth: scroll?.scrollWidth ?? 0,
      clientWidth: scroll?.clientWidth ?? 0,
    };
  });
  expect(mobile.width).toBeGreaterThanOrEqual(44);
  expect(mobile.height).toBeGreaterThanOrEqual(44);
  expect(mobile.pageWidth).toBeLessThanOrEqual(mobile.viewportWidth);
  expect(mobile.scrollWidth).toBeGreaterThan(mobile.clientWidth);
  await page.locator('.card').first().focus();
  for (let count = 0; count < 15; count += 1) await page.keyboard.press('ArrowDown');
  for (let count = 0; count < 15; count += 1) await page.keyboard.press('ArrowRight');
  await expect(page.getByRole('button', { name: 'Row 16, column 16, closed' })).toBeFocused();

  await page.setViewportSize({ width: 640, height: 400 });
  const zoom = await page.locator('.card').last().evaluate((card) => ({
    width: card.getBoundingClientRect().width,
    pageWidth: card.ownerDocument.documentElement.scrollWidth,
    viewportWidth: card.ownerDocument.documentElement.clientWidth,
  }));
  expect(zoom.width).toBeGreaterThanOrEqual(44);
  expect(zoom.pageWidth).toBeLessThanOrEqual(zoom.viewportWidth);
  await expect(board.locator('button').last()).toBeFocused();
});

async function moveTo(page: Page, from: number, to: number, size: number): Promise<void> {
  let row = Math.floor(from / size);
  let column = from % size;
  const targetRow = Math.floor(to / size);
  const targetColumn = to % size;
  while (row < targetRow) { await page.keyboard.press('ArrowDown'); row += 1; }
  while (row > targetRow) { await page.keyboard.press('ArrowUp'); row -= 1; }
  while (column < targetColumn) { await page.keyboard.press('ArrowRight'); column += 1; }
  while (column > targetColumn) { await page.keyboard.press('ArrowLeft'); column -= 1; }
  await expectFocusedCard(page, to, 'closed');
}

async function expectFocusedCard(page: Page, index: number, state: 'closed'): Promise<void> {
  const row = Math.floor(index / 4) + 1;
  const column = index % 4 + 1;
  await expect(page.getByRole('button', { name: `Row ${row}, column ${column}, ${state}` })).toBeFocused();
}

