  const announce = useCallback((text: string) => {
    announcementId.current += 1;
    setAnnouncement({ id: announcementId.current, text });
  }, []);

  const replaceGame = useCallback((next: typeof game, shouldPause: boolean) => {
    revisionRef.current += 1;
    setRevision(revisionRef.current);
    commit(next);
    setPaused(shouldPause);
    setCelebrate(false);
    setBoardDraft(next.board.code);
  }, [commit]);

  const newGame = useCallback(() => {
    syncClock();
    replaceGame(freshGame(gameRef.current.board.size, gameRef.current.board.code), false);
  }, [replaceGame, syncClock]);

  const restart = useCallback(() => {
    syncClock();
    const next = createGame(gameRef.current.board.code);
    if (next) replaceGame(next, false);
  }, [replaceGame, syncClock]);

  const changeSize = useCallback((value: number) => {
    const size = parseSize(value);
    if (!size) return;
    syncClock();
    saveSize(size);
    replaceGame(freshGame(size, gameRef.current.board.code), false);
  }, [replaceGame, syncClock]);

  const loadBoard = useCallback(() => {
    syncClock();
    const next = createGame(boardDraft.trim());
    if (!next) { announce('Invalid board code.'); return; }
    saveSize(next.board.size);
    replaceGame(next, false);
  }, [announce, boardDraft, replaceGame, syncClock]);

  const exportSnapshot = useCallback(() => {
    setSnapshotDraft(encodeSnapshot(gameRef.current));
  }, []);

  const loadSnapshot = useCallback(() => {
    syncClock();
    const next = decodeSnapshot(snapshotDraft);
    if (!next) { announce('Invalid snapshot.'); return; }
    saveSize(next.board.size);
    const completed = isWon(next);
    replaceGame(next, !completed);
    announce(completed ? 'Loaded completed snapshot.' : 'Loaded snapshot. Select Resume to continue.');
  }, [announce, replaceGame, snapshotDraft, syncClock]);

  const activate = useCallback((index: number) => {
    if (paused) return;
    syncClock();
    const previous = gameRef.current;
    const next = activateCard(previous, index);
    commit(next);
    const message = turnResult(previous, next);
    if (message) announce(message);
    if (!isWon(previous) && isWon(next)) {
      setCelebrate(true);
      const best = bestRef.current.get(next.board.size);
      if (best === undefined || next.moves < best) {
        const updated = new Map(bestRef.current);
        updated.set(next.board.size, next.moves);
        bestRef.current = updated;
        setBestScores(updated);
        saveBestScores(updated);
      }
    }
  }, [announce, commit, paused, syncClock]);

  const resume = useCallback(() => { setPaused(false); }, []);

  return {
    game, paused, boardDraft, snapshotDraft, best: bestScores.get(game.board.size),
    announcement, celebrate, revision, setBoardDraft, setSnapshotDraft,
    newGame, restart, changeSize, loadBoard, exportSnapshot, loadSnapshot, activate, resume,
  };
}

function freshGame(size: GridSize, avoidCode?: string) {
  let code = '';
  do { code = `np1-${size}-${randomSeed()}`; } while (code === avoidCode);
  const game = createGame(code);
  if (!game) throw new Error('Could not create a game from a generated board code.');
  return game;
}

function randomSeed(): number {
  const values = new Uint32Array(1);
  if (typeof crypto !== 'undefined' && typeof crypto.getRandomValues === 'function') {
    crypto.getRandomValues(values);
    return (values[0] ?? 0) % 2_147_483_646 + 1;
  }
  return Math.floor(Math.random() * 2_147_483_646) + 1;
}

function parseSize(value: number): GridSize | null {
  if (value === 4 || value === 6 || value === 8 || value === 10 || value === 12 || value === 14 || value === 16) return value;
  return null;
}
import { GRID_SIZES, MAX_MOVES } from '../constants';
import type { GridSize } from '../types';

const SIZE_KEY = 'neon-pairs.preferences.v1';
const BEST_KEY = 'neon-pairs.best.v1';

export function readSavedSize(): GridSize | null {
  try {
    const value: unknown = JSON.parse(window.localStorage.getItem(SIZE_KEY) ?? 'null');
    if (!isRecord(value) || !isGridSize(value.size)) return null;
    return value.size;
  } catch { return null; }
}

export function saveSize(size: GridSize): void {
  try { window.localStorage.setItem(SIZE_KEY, JSON.stringify({ size })); } catch { /* Storage is optional. */ }
}

export function readBestScores(): Map<GridSize, number> {
  const scores = new Map<GridSize, number>();
  try {
    const value: unknown = JSON.parse(window.localStorage.getItem(BEST_KEY) ?? 'null');
    if (!isRecord(value)) return scores;
    for (const [key, score] of Object.entries(value)) {
      const size = Number(key);
      if (isGridSize(size) && typeof score === 'number' && Number.isSafeInteger(score) && score >= 0 && score <= MAX_MOVES) {
        scores.set(size, score);
      }
    }
  } catch { /* A corrupt record is ignored. */ }
  return scores;
}

export function saveBestScores(scores: ReadonlyMap<GridSize, number>): void {
  const value: Record<string, number> = {};
  for (const [size, moves] of scores) value[String(size)] = moves;
  try { window.localStorage.setItem(BEST_KEY, JSON.stringify(value)); } catch { /* Storage is optional. */ }
}

function isGridSize(value: unknown): value is GridSize {
  return typeof value === 'number' && GRID_SIZES.some((size) => size === value);
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}
const COLORS = ['#63E7FF', '#FF71D6', '#8BEA7D', '#FFE082', '#FFB064', '#B49AFF', '#FF8296', '#D9F3FF'] as const;
const COLOR_NAMES = ['cyan', 'magenta', 'green', 'yellow', 'orange', 'violet', 'rose', 'ice'] as const;
const SHAPES = ['circle', 'square', 'triangle', 'diamond', 'star', 'hexagon', 'plus', 'chevron'] as const;
const MARKERS = ['top', 'top-right', 'right', 'bottom-right', 'bottom', 'bottom-left', 'left', 'top-left'] as const;
const POINTS = [
  '',
  '27,27 73,27 73,73 27,73',
  '50,26 75,72 25,72',
  '50,26 74,50 50,74 26,50',
  '50,26 56,42 74,42 60,53 65,72 50,61 35,72 40,53 26,42 44,42',
  '50,26 71,38 71,62 50,74 29,62 29,38',
  '38,27 62,27 62,42 74,42 74,58 62,58 62,73 38,73 38,58 26,58 26,42 38,42',
  '27,28 73,50 27,72 38,50',
] as const;
const MARKER_OFFSETS = [
  [0, -40], [28.284, -28.284], [40, 0], [28.284, 28.284],
  [0, 40], [-28.284, 28.284], [-40, 0], [-28.284, -28.284],
] as const;

export type FaceInfo = Readonly<{ name: string; color: string; fill: 'solid' | 'outline'; shape: string; marker: string }>;

export function faceInfo(id: number): FaceInfo {
  const shapeIndex = id % 8;
  const markerIndex = Math.floor(id / 8) % 8;
  const fill = id < 64 ? 'solid' : 'outline';
  const color = COLORS[markerIndex] ?? COLORS[0];
  const colorName = COLOR_NAMES[markerIndex] ?? COLOR_NAMES[0];
  const shape = SHAPES[shapeIndex] ?? SHAPES[0];
  const marker = MARKERS[markerIndex] ?? MARKERS[0];
  return { name: `${colorName} ${fill} ${shape}, marker ${marker}`, color, fill, shape, marker };
}

export function faceShapePoints(id: number): string {
  return POINTS[id % 8] ?? POINTS[0];
}

export function markerOffset(id: number): readonly [number, number] {
  return MARKER_OFFSETS[Math.floor(id / 8) % 8] ?? MARKER_OFFSETS[0];
}

